<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Authorship\AuthorshipOfficeProvisioningService; use Symfony\Component\Console\Attribute\AsCommand; use Symfony\Component\Console\Command\Command; use Symfony\Component\Console\Input\InputArgument; use Symfony\Component\Console\Input\InputInterface; use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name: 'imperium:mastermason:prepare-studium', description: 'Open the canonical Chancellor provisioning case')]
final class MasterMasonPrepareStudiumCommand extends Command { public function __construct(private readonly AuthorshipOfficeProvisioningService $service) { parent::__construct(); } protected function configure(): void { $this->addArgument('demand-id', InputArgument::REQUIRED); } protected function execute(InputInterface $input, OutputInterface $output): int { try { $case = $this->service->open('studium', (string) $input->getArgument('demand-id')); } catch (\Throwable $e) { $output->writeln('<error>REFUSED</error> '.$e->getMessage()); return self::FAILURE; } $output->writeln('<info>STUDIUM_PROVISIONING_OPENED</info> '.$case['case_id']); $output->writeln('Seat: '.$case['seat'].' CANONICAL_STAFF_READY'); $output->writeln('Subordinate Notary resolution: PENDING CHANCELLOR'); $output->writeln('Spawning authority: NOT GRANTED'); $output->writeln('Execution authority: NOT GRANTED'); return self::SUCCESS; } }
